#!/usr/bin/env bash
# scripts/destroy.sh
# Destroy a deployed scenario and clean up the Terraform workspace
# Usage: ./scripts/destroy.sh [scenario_name]
# Generated by: INFRA_AGENT during /phase 5

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
SCENARIOS_DIR="${REPO_ROOT}/terraform/scenarios"

RED='\033[0;31m'; GREEN='\033[0;32m'; YELLOW='\033[1;33m'
CYAN='\033[0;36m'; BOLD='\033[1m'; RESET='\033[0m'

for cmd in terraform; do
  if ! command -v "$cmd" &>/dev/null; then
    echo -e "${RED}❌ Required command not found: $cmd${RESET}"; exit 1
  fi
done

if [[ -z "${PROXMOX_VE_API_TOKEN_ID:-}" || -z "${PROXMOX_VE_API_TOKEN_SECRET:-}" ]]; then
  echo -e "${YELLOW}⚠️  Proxmox credentials not set. Run: source scripts/lab-env.local.sh${RESET}"
  exit 1
fi

# ── Select scenario ──────────────────────────────────────────────────────────
if [[ $# -gt 0 ]]; then
  SELECTED_SCENARIO="$1"
else
  # List active workspaces
  ACTIVE_WORKSPACES=()
  while IFS= read -r line; do
    ws=$(echo "$line" | tr -d '* ' | xargs)
    [[ "$ws" != "default" && -n "$ws" ]] && ACTIVE_WORKSPACES+=("$ws")
  done < <(cd "${SCENARIOS_DIR}/$(ls "${SCENARIOS_DIR}" | head -1)" && terraform workspace list 2>/dev/null || echo "")

  if [[ ${#ACTIVE_WORKSPACES[@]} -eq 0 ]]; then
    echo "No active scenario workspaces found."; exit 0
  fi

  echo ""
  echo -e "${BOLD}Active scenarios:${RESET}"
  for i in "${!ACTIVE_WORKSPACES[@]}"; do
    echo -e "  ${CYAN}[$((i+1))]${RESET} ${ACTIVE_WORKSPACES[$i]}"
  done
  echo ""
  echo -n "Select scenario to destroy [1-${#ACTIVE_WORKSPACES[@]}]: "
  read -r SELECTION

  if ! [[ "$SELECTION" =~ ^[0-9]+$ ]] || \
     [[ "$SELECTION" -lt 1 ]] || \
     [[ "$SELECTION" -gt ${#ACTIVE_WORKSPACES[@]} ]]; then
    echo -e "${RED}Invalid selection${RESET}"; exit 1
  fi
  SELECTED_SCENARIO="${ACTIVE_WORKSPACES[$((SELECTION-1))]}"
fi

SCENARIO_DIR="${SCENARIOS_DIR}/${SELECTED_SCENARIO}"

if [[ ! -d "$SCENARIO_DIR" ]]; then
  echo -e "${RED}❌ Scenario directory not found: ${SELECTED_SCENARIO}${RESET}"; exit 1
fi

echo ""
echo -e "${RED}⚠️  This will DESTROY all VMs in scenario: ${BOLD}${SELECTED_SCENARIO}${RESET}"
echo -e "${YELLOW}All unsaved student work will be lost.${RESET}"
echo ""
echo -n "Type the scenario name to confirm: "
read -r CONFIRM_NAME

if [[ "$CONFIRM_NAME" != "$SELECTED_SCENARIO" ]]; then
  echo "Confirmation did not match. Aborting."; exit 1
fi

cd "${SCENARIO_DIR}"
terraform workspace select "${SELECTED_SCENARIO}"

echo -e "${CYAN}→ Running terraform destroy...${RESET}"
terraform destroy -var-file=terraform.tfvars -input=false -auto-approve

echo -e "${CYAN}→ Removing workspace...${RESET}"
terraform workspace select default
terraform workspace delete "${SELECTED_SCENARIO}"

echo ""
echo -e "${GREEN}✅ Scenario ${SELECTED_SCENARIO} destroyed and workspace cleaned up${RESET}"
echo ""
